# shellcheck shell=bash
# btop color theme (dark). Load gradients run calm -> hot: emerald, warm, pink.
# Output: ports/btop/terminal-noir.theme

build_btop() {
    jq -r '
        .variants.dark as $c
        | def t($k; $v): "theme[\($k)]=\"\($v)\"";
          def grad($k; $a; $b; $z): t($k + "_start"; $a), t($k + "_mid"; $b), t($k + "_end"; $z);
        "# Terminal Noir for btop. https://terminalnoir.web.app",
        "# Generated by scripts/build from palette/palette.json.",
        "",
        t("main_bg"; $c.surface.base),
        t("main_fg"; $c.text.primary),
        t("title"; $c.accent.primary),
        t("hi_fg"; $c.accent.primary),
        t("selected_bg"; $c.surface.elevated),
        t("selected_fg"; $c.text.primary),
        t("inactive_fg"; $c.text.faint),
        t("graph_text"; $c.text.muted),
        t("meter_bg"; $c.surface.elevated),
        t("proc_misc"; $c.accent.success),
        t("cpu_box"; $c.surface.outline),
        t("mem_box"; $c.surface.outline),
        t("net_box"; $c.surface.outline),
        t("proc_box"; $c.surface.outline),
        t("div_line"; $c.surface.border),
        grad("temp"; $c.accent.success; $c.accent.warning; $c.accent.error),
        grad("cpu"; $c.accent.success; $c.accent.warning; $c.accent.error),
        grad("used"; $c.accent.success; $c.accent.warning; $c.accent.error),
        grad("free"; $c.ansi.normal.blue; $c.ansi.bright.blue; $c.text.primary),
        grad("cached"; $c.ansi.normal.cyan; $c.ansi.bright.cyan; $c.text.primary),
        grad("available"; $c.accent.success; $c.ansi.bright.green; $c.text.primary),
        grad("download"; $c.ansi.normal.blue; $c.accent.info; $c.text.primary),
        grad("upload"; $c.accent.primary; $c.accent.warning; $c.text.primary),
        grad("process"; $c.accent.success; $c.accent.warning; $c.accent.error)
    ' "$PALETTE" > "$OUT/ports/btop/terminal-noir.theme"
}
